  "supportive_card_ids": ["C10", "C17", "C34", "C41"],
  "contradictory_card_ids": [],
  "prediction_basis_card_ids": ["C10", "C17"],
  "claims": [
    {
      "claim": "The query is a statin bearing the same 3,5-dihydroxyhept-6-enoic acid side chain and 4-fluorophenyl motif as cerivastatin, whose absolute oral bioavailability was 60% (90% CI 51-70%) in fasted healthy young men, well above the 20% threshold.",
      "card_ids": ["C10", "C17"]
    },
    {
      "claim": "L3 oral-exposure records for related statins show measurable plasma exposure after oral dosing (e.g., fluvastatin Cmax 94.1 ng/mL and tmax 0.5 h; rosuvastatin AUC0-inf about 225 ng·h/mL), consistent with oral absorption of this statin class, but none provides an absolute F value for the query.",
      "card_ids": ["C34", "C41", "C40", "C45"]
    },
    {
      "claim": "No visible record affirmatively supports F < 20% for the query; the lowest visible L1 gold values (propranolol fasted 27.2%, paliperidone 28%) are still above threshold and belong to different molecules.",
      "card_ids": ["C07", "C22", "C03"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "oral_auc_cmax_exposure",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "no_change",
      "card_ids": ["C34", "C35", "C36", "C37", "C38", "C39", "C40", "C41", "C42", "C43", "C44", "C45"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query (pitavastatin) is present in the supplied records.",
    "L3 records are oral exposure data for other statins (atorvastatin, rosuvastatin, fluvastatin) and flurbiprofen, not for the query, and do not quantify F.",
    "No query-specific data on first-pass metabolism, transporter-mediated disposition, solubility, or permeability are provided beyond physicochemical priors.",
    "The query is fully ionized at physiological pH (neutral fraction 0), which may limit passive permeability, but the impact is unknown and is not affirmative evidence for F < 20%."
  ],
  "decision_summary": "Predicted high because the query is a statin with the same dihydroxyheptenoic acid side chain and 4-fluorophenyl motif as cerivastatin, whose absolute oral bioavailability was 60% (90% CI 51-70%); L3 oral-exposure records for related statins are consistent with oral absorption but do not provide a query-specific F value, so confidence remains moderate and the prior high prediction is kept."
}

